HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>AnviRoute</title><script>try{document.documentElement.dataset.theme=localStorage.getItem('anviroute-theme')||'dark'}catch{document.documentElement.dataset.theme='dark'}</script><style>
:root{color-scheme:dark;--bg:#171916;--text:#e7e9e1;--sidebar:#1d201b;--border:#383d32;--muted:#a4ac99;--panel:#23271f;--accent:#697e4c;--focus:#a2bb7840;--badge:#303c25;--success:#b6d48c;--link:#bdcf9f;--code:#10120f;--danger:#ffac98}
:root[data-theme="light"]{color-scheme:light;--bg:#f5f2eb;--text:#262822;--sidebar:#eeece3;--border:#deded2;--muted:#74766b;--panel:#fffefa;--accent:#69744d;--focus:#69744d40;--badge:#e9eddc;--success:#535f36;--link:#59663e;--code:#292c25;--danger:#a44e39}
code,.mark{color:#f5f2eb!important}.mark{background:var(--accent)}.row label{display:block;margin-top:14px}.row:last-child{border-bottom:0}input::placeholder{color:var(--muted);opacity:.8}button:focus-visible,a:focus-visible{outline:2px solid var(--link);outline-offset:3px}

*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 'Segoe UI',system-ui,sans-serif}.shell{display:grid;grid-template-columns:220px 1fr;min-height:100vh}aside{background:var(--sidebar);border-right:1px solid var(--border);padding:34px 22px;display:flex;flex-direction:column;gap:36px}.brand{font-size:25px;font-weight:700;letter-spacing:-1px}.brand small{display:block;font-size:10px;letter-spacing:2px;text-transform:uppercase;font-weight:400}.mark{background:var(--accent);color:var(--bg);border-radius:8px;display:inline-block;padding:0 10px;margin-right:6px}nav{display:grid;gap:8px}nav a{text-decoration:none;color:var(--muted);padding:12px;border-radius:8px}nav a.current{background:var(--panel);color:var(--text);font-weight:600}.aside-foot{margin-top:auto;font-size:12px;color:var(--muted)}main{width:100%;max-width:1320px;margin:auto;padding:38px 44px}h1{font-size:34px;letter-spacing:-1px;margin:0}h1 span{color:var(--accent)}p,small{color:var(--muted)}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.eyebrow{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--muted)}.badge{border:1px solid var(--border);background:var(--badge);padding:7px 12px;border-radius:24px;color:var(--success);font-size:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:var(--panel);border:1px solid var(--border);border-radius:12px;padding:24px;margin-bottom:20px}h2{font-size:18px;margin:0 0 16px}input,select,textarea,button{font:inherit;border-radius:7px;padding:10px 12px;border:1px solid var(--border)}textarea{width:100%;min-height:94px;resize:vertical;background:var(--panel);color:inherit;margin:6px 0 12px}summary{cursor:pointer;color:var(--link);margin:12px 0}input,select{background:var(--panel);color:inherit;width:100%;margin:6px 0 16px}input:focus,select:focus{outline:2px solid var(--focus);border-color:var(--accent)}label{font-size:12px;color:var(--muted)}button{cursor:pointer;background:var(--accent);color:white;font-weight:500;margin:3px 6px 3px 0}button:hover{filter:brightness(.94)}button:disabled{opacity:.5;cursor:wait}button.secondary{background:transparent;color:var(--text)}code{color:var(--bg);background:var(--code);padding:15px;border-radius:8px;display:block;overflow-wrap:anywhere;font:13px/1.6 Consolas,monospace}.row{padding:14px 0;border-bottom:1px solid var(--border)}.ok{color:var(--success)}.bad{color:var(--danger)}#notice{min-height:24px;white-space:pre-wrap}#events{max-height:320px;overflow:auto;font-size:13px}.flow{display:flex;gap:16px;justify-content:space-between;flex-wrap:wrap}.flow div{border:1px solid var(--border);padding:18px;border-radius:8px;flex:1;min-width:180px}.flow small{display:block;margin-top:6px}a{color:var(--link)}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.stat{font-size:18px;font-weight:600;overflow-wrap:anywhere;margin-top:10px}.filters{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.filters select{width:180px}.filters input[type=search]{flex:1;min-width:150px}.filters label{white-space:nowrap}.filters input[type=checkbox]{width:auto;accent-color:var(--accent)}table{border-collapse:collapse;width:100%;font-size:12px;text-align:left}th{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:1px}th,td{padding:14px 10px;border-bottom:1px solid var(--border);vertical-align:top}td:last-child{min-width:230px;overflow-wrap:anywhere}.table-wrap{overflow:auto}.empty{padding:35px;text-align:center;color:var(--muted)}footer{font-size:12px;color:var(--muted);margin-top:28px}[hidden]{display:none!important}@media(max-width:1000px){main{padding:26px}.shell{grid-template-columns:180px 1fr}aside{padding:28px 15px}.grid{grid-template-columns:1fr}.brand{font-size:22px}}@media(max-width:650px){.shell{display:block}aside{padding:18px;gap:15px;border-right:0}nav{display:flex;gap:2px}nav a{padding:8px}.aside-foot{display:none}main{padding:22px 16px}.stats{grid-template-columns:1fr;gap:0}header{align-items:start;gap:12px;flex-direction:column}h1{font-size:29px}}
.test-result{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--bg);border-left:3px solid var(--accent);padding:14px;margin-top:12px;border-radius:6px}.connection-state{font-size:12px;margin:10px 0}.row{padding:22px 0}textarea:focus{outline:2px solid var(--focus)}.row code{font-size:12px}#notice:not(:empty){padding:12px 16px;background:var(--panel);border:1px solid var(--border);border-radius:8px}</style></head><body><div class="shell"><aside><div class="brand"><span class="mark">a</span>AnviRoute<small>Your local routing desk</small></div><nav aria-label="Main"><a href="/overview">Overview</a><a href="/connections">Connections</a><a href="/logs">Error logs</a></nav><div class="aside-foot">● Local service<br><span id="local-address">127.0.0.1:20128</span><br><br>Standard library only</div></aside><main><header><div><div class="eyebrow">Workspace / <span id="page-name">Overview</span></div><h1 id="page-title">Your models, connected.</h1><p>A quiet place to keep Claude and your APIs in sync.</p></div><div><button id="theme" class="secondary" type="button">Light theme</button><div class="badge">Local service · <span id="version"></span></div></div></header><p id="notice" role="status"></p>
<section id="overview"><div class="stats"><div class="card"><div class="eyebrow">Active profile</div><div id="profile-stat" class="stat">Add a connection</div><small>Saved once for your next session</small></div><div class="card"><div class="eyebrow">Selected model</div><div id="model-stat" class="stat">—</div><small>Passed automatically to Claude</small></div><div class="card"><div class="eyebrow">Connection check</div><div id="ready-stat" class="stat">Setup required</div><small>Authentication, model, and inference</small></div></div><div class="card"><h2>Connection path</h2><div class="flow"><div>Claude Code → AnviRoute<small id="client">Waiting for Claude</small></div><div>AnviRoute adapter<small id="adapter">Listening locally</small></div><div>AnviRoute → API / Kaggle<small id="upstream">Not checked</small></div></div><p>Second terminal, inside your project: <code>anviroute run claude --modename qwen</code></p></div>
<div class="grid"><div class="card"><div class="eyebrow">Terminal 1</div><h2>Keep the router running</h2><code id="start-command">anviroute</code><p>Configure your API in the Connections page.</p></div><div class="card"><div class="eyebrow">Terminal 2 / Your project</div><h2>Start Claude Code</h2><code>anviroute run claude --modename qwen</code><p>No URL, key, or model prompts.</p></div></div><a href="/connections">Manage connections →</a></section><section id="connections"><div class="grid"><section><div class="card"><h2>Your saved models</h2><div id="providers"></div></div><div class="card"><h2 id="form-title">Add a model</h2><form id="form"><input id="id" type="hidden"><label>Saved model name<input id="name" required placeholder="qwen"></label><label>API URL<input id="url" type="url" required placeholder="https://your-session.trycloudflare.com/v1"></label><label>API key<input id="key" type="password" autocomplete="off" placeholder="Blank keeps existing key when editing"></label><details><summary>Model, context and API format (optional)</summary><label>API format<select id="format"><option value="openai">OpenAI-compatible / Ollama</option><option value="anthropic">Anthropic Messages</option></select></label><label>Model (optional)<input id="model" placeholder="Leave blank to detect automatically"></label><label>Context window (tokens)<input id="context_tokens" type="number" min="1024" max="2000000" placeholder="32768 for the Kaggle example"></label><small>Match Ollama’s configured context. Blank uses Claude’s default.</small></details><button id="save">Save &amp; connect</button><button type="button" class="secondary" id="clear">New connection</button></form><small><span id="credential-storage"></span>. Blank key keeps an existing saved key.</small></div></section>
<section><div class="card"><h2>Just two commands</h2><p>1. Open this frontend:</p><code>anviroute</code><p>2. Start Claude from any project folder:</p><code id="launch-command">anviroute run claude --modename qwen</code><p>Your saved name selects the model. No separate activation or check step.</p></div><div class="card"><h2>New Kaggle session?</h2><p>Enter the new URL and API key in your saved model and click <b>Save &amp; reconnect</b>. The name and Claude command stay the same.</p><small>A random Cloudflare URL cannot be discovered from your PC alone. Enter the current address after restarting Kaggle.</small></div><div class="card"><h2>Slow replies?</h2><p>Send a test message to measure a short reply. Error logs show duration, input/output tokens and tool count for Claude requests.</p><p>Random Cloudflare tunnels buffer the full reply. Large contexts, thinking, and CPU offloading add delay. Check <b>ollama ps</b> in Kaggle for GPU usage.</p><small>Keeping a model warm does not prevent Kaggle session shutdown. Restart the notebook and update this saved connection after shutdown.</small></div></section></div></section><section id="logs"><div class="card"><h2>Error logs</h2><p>Trace issues from Claude through the adapter to your API.</p><div class="filters"><select id="stage" aria-label="Filter stage"><option value="">All stages</option><option value="client">Claude → AnviRoute</option><option value="adapter">Adapter</option><option value="upstream">AnviRoute → API</option></select><input id="search" type="search" placeholder="Search logs…" aria-label="Search logs"><label><input id="errors-only" type="checkbox" checked> Errors only</label><button class="secondary" id="export">Export JSON</button></div><div class="table-wrap"><table><thead><tr><th>Timestamp</th><th>Stage</th><th>Status</th><th>Profile</th><th>Message</th></tr></thead><tbody id="log-rows"></tbody></table></div><div class="empty" id="empty">No errors recorded. Your routing desk is quiet.</div></div><div class="card"><h2>Find the right fix</h2><p><b>Claude → AnviRoute:</b> keep the service terminal running and start Claude with the AnviRoute command.</p><p><b>Adapter:</b> inspect the message for unsupported request or response content.</p><p><b>AnviRoute → API:</b> check Kaggle, tunnel URL, API key, model availability, and rate limits. Save changes and check again.</p><small>Up to 500 recent events. Rotating logs use about 768 KB maximum. Prompts, replies, and credentials are excluded.</small></div></section><footer>AnviRoute · Local by default. Yours to configure.</footer></main></div><script>
const token=__TOKEN__;
function applyTheme(theme){document.documentElement.dataset.theme=theme;document.getElementById('theme').textContent=theme==='dark'?'Light theme':'Dark theme';try{localStorage.setItem('anviroute-theme',theme)}catch{}}
applyTheme(document.documentElement.dataset.theme||'dark');document.getElementById('theme').onclick=()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');let state={providers:[]},providerSignature="",pending=0;const $=id=>document.getElementById(id);function msg(t,bad=false){$('notice').textContent=t;$('notice').className=bad?'bad':'ok'}
async function api(path,data){if(data)pending++;try{let r=await fetch('/control/'+path,{method:data?'POST':'GET',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});let j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}finally{if(data)pending--}}
function button(label,action){let b=document.createElement('button');b.textContent=label;b.className='secondary';b.onclick=()=>action().catch(e=>msg(e.message,true));return b}
async function refresh(){try{state=await api('status');$('version').textContent=state.version;$('local-address').textContent=state.address.replace('http://','');$('client').textContent=state.client_seen?'Request received · '+state.client_seen:'Waiting for Claude';$('adapter').textContent=state.address;$('upstream').textContent=state.upstream||'Not checked';let a=state.providers.find(p=>p.id===state.active);$('launch-command').textContent='anviroute run claude --modename '+quote(a?.name||'qwen');const signature=JSON.stringify([state.providers,state.active]);if(signature!==providerSignature&&!pending&&!$('providers').contains(document.activeElement)){providerSignature=signature;$('providers').replaceChildren();for(let p of state.providers){let r=document.createElement('div');r.className='row';let t=document.createElement('p');t.textContent=(p.id===state.active?'● ':'')+p.name+' · '+(p.model||'Auto-detect');let health=document.createElement('div');health.className='connection-state';health.id='health-'+p.id;let cmd=document.createElement('code');cmd.textContent='anviroute run claude --modename '+quote(p.name);let urlInput=document.createElement('input');urlInput.type='url';urlInput.value=p.url;urlInput.required=true;urlInput.setAttribute('aria-label','API URL for '+p.name);let urlLabel=document.createElement('label');urlLabel.textContent='API URL';urlLabel.append(urlInput);let keyInput=document.createElement('input');keyInput.type='password';keyInput.autocomplete='off';keyInput.placeholder=p.key_saved?'Saved key · leave blank to keep it':'Enter API key';keyInput.setAttribute('aria-label','API key for '+p.name);let keyLabel=document.createElement('label');keyLabel.textContent='API key';keyLabel.append(keyInput);let resultBox=document.createElement('div');resultBox.className='test-result';resultBox.hidden=true;resultBox.setAttribute('role','status');let update=button('Save & reconnect',async()=>{if(!urlInput.reportValidity())return;update.disabled=true;resultBox.hidden=false;resultBox.textContent='Saving and checking the connection…';try{const result=await api('connect',{id:p.id,name:p.name,url:urlInput.value.trim(),key:keyInput.value.trim(),model:p.model,format:p.format});keyInput.value='';resultBox.textContent=result.message;msg(result.message,!result.ready);await refresh()}catch(e){resultBox.textContent=e.message;throw e}finally{update.disabled=false}});let prompt=document.createElement('input');prompt.placeholder='Test message (optional)';prompt.setAttribute('aria-label','Test message for '+p.name);let test=button('Send test message',async()=>{test.disabled=true;resultBox.hidden=false;resultBox.textContent='Waiting for the model… A cold model can take longer.';const started=Date.now();const timer=setInterval(()=>{resultBox.textContent='Waiting for the model · '+Math.floor((Date.now()-started)/1000)+'s';},1000);try{const result=await api('test',{name:p.name,prompt:prompt.value||'Hello. Reply briefly to verify this connection.'});resultBox.textContent=result.reply+'\n\n'+result.seconds+'s · Input '+(result.usage.input_tokens??0)+' / output '+(result.usage.output_tokens??0)+' tokens';msg('Test reply received')}catch(e){resultBox.textContent=e.message;msg(e.message,true)}finally{clearInterval(timer);test.disabled=false;await refresh()}});r.append(t,health,cmd,urlLabel,keyLabel,update,prompt,test,resultBox,button('Edit model',async()=>{for(let k of ['id','name','url','model','context_tokens'])$(k).value=p[k]||'';$('format').value=p.format;$('key').value='';$('form-title').textContent='Edit '+p.name;$('name').focus()}),button('Remove',async()=>{if(confirm('Remove '+p.name+'?')){await api('remove',{id:p.id});await refresh()}}));$('providers').append(r)}}for(let p of state.providers){let h=$('health-'+p.id),d=state.diagnostics?.[p.id];if(h){h.textContent=d?(d.ok?'✓ ':'× ')+d.message+(d.seconds!==undefined?' · '+d.seconds+'s':'')+' · '+d.time:'Not tested this session';h.className='connection-state '+(d?.ok?'ok':d?'bad':'')}}$('profile-stat').textContent=a?a.name:'Add a connection';$('model-stat').textContent=state.model||'—';$('ready-stat').textContent=state.ready?'Connection verified':'Check required';$('credential-storage').textContent=state.credential_storage;$('start-command').textContent='anviroute';renderLogs()}catch(e){msg(e.message,true)}}
function quote(name){return /^[a-zA-Z0-9_-]+$/.test(name)?name:JSON.stringify(name)}
$('form').onsubmit=async e=>{e.preventDefault();$('save').disabled=true;msg('Saving and connecting…');try{let r=await api('connect',{id:$('id').value,name:$('name').value,url:$('url').value,key:$('key').value,model:$('model').value,context_tokens:$('context_tokens').value,format:$('format').value});$('id').value=r.id;$('key').value='';msg(r.message,!r.ready);await refresh()}catch(e){msg(e.message,true)}finally{$('save').disabled=false}};
$('clear').onclick=()=>{$('form').reset();$('id').value='';$('form-title').textContent='Add a model'};
const page=location.pathname==='/logs'?'logs':location.pathname==='/overview'?'overview':'connections';
for(let p of ['overview','connections','logs'])$(p).hidden=p!==page;
$('page-name').textContent=page[0].toUpperCase()+page.slice(1);if(page==='logs')$('page-title').textContent='A clearer view of errors.';if(page==='connections')$('page-title').textContent='Add once. Update in seconds.';
document.querySelector('nav a[href="'+(page==='overview'?'/overview':page==='logs'?'/logs':'/connections')+'"]').classList.add('current');
function filtered(){return [...(state.events||[])].reverse().filter(e=>(!$('errors-only').checked||!e.ok)&&(!$('stage').value||e.stage===$('stage').value)&&JSON.stringify(e).toLowerCase().includes($('search').value.toLowerCase()))}
function renderLogs(){const list=filtered();$('log-rows').replaceChildren();for(let e of list){let tr=document.createElement('tr');for(let value of [e.time,e.stage,e.status??(e.ok?'OK':'Error'),e.profile||'—',e.message]){let td=document.createElement('td');td.textContent=value;td.className=e.ok?'':'bad';tr.append(td)}$('log-rows').append(tr)}$('empty').hidden=!!list.length}
for(let id of ['stage','search','errors-only'])$(id).oninput=renderLogs;
$('export').onclick=()=>{let u=URL.createObjectURL(new Blob([JSON.stringify(filtered(),null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download='anviroute-events.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
refresh();setInterval(refresh,4000);
</script></body></html>'''
